%[text] # Loops and Iteration
%[text] To illustrate using loops to implement an incremental operation, and generating 2D plots, consider the following scenario:
%[text] How does compound interest grow your TSP account?
%[text] - 30 year old contributing the max: \\$24,500
%[text] - Each year they plan to make 5% return total investment
%[text] - How much would that investment be worth when they are 55? \
%[text] ## Manual Iteration
%[text] How much would you make the first year?
principal = 24500;
r = 0.05;
return_year1 = principal * r %[output:975b8670]
%[text] So how much to I have to invest in year two?
new_principal = principal + return_year1 %[output:18c5e778]
%[text] And how much will you make in the second year?
return_year2 = new_principal * r %[output:139edb9a]
%[text] And now we have yet more to invest in the third year
new_prince = new_principal + return_year2 %[output:8da349d9]
return_year3 = new_principal * r %[output:2752ab51]
%[text] So we start to see a pattern
%[text] $P\[n+1\]=P\[n\](1+r)$
P0 = principal %[output:0730def6]
P1 = P0*(1+r) %[output:343a54a3]
P2 = P1*(1+r) %[output:2d773aff]
P3 = P2*(1+r) %[output:6ca0eac3]
P4 = P3*(1+r) %[output:96b0c6b6]
P5 = P4*(1+r) %[output:9b162b48]
%[text] Visualize with a plot:
figure(1); %[output:55a0c377]
clf(); %[output:55a0c377]
plot(30,P0, 'o') %[output:55a0c377]
hold("on") %[output:55a0c377]
plot(31, P1, 'o') %[output:55a0c377]
plot(32, P2, 'o') %[output:55a0c377]
plot(33, P3, 'o') %[output:55a0c377]
plot(34, P4, 'o') %[output:55a0c377]
plot(35, P5, 'o') %[output:55a0c377]
%[text] Labels with units!
xlabel("Age [years]") %[output:55a0c377]
ylabel("Principal [$]") %[output:55a0c377]
%[text] 
%[text] ## for Loop Iteration
%[text] ![](text:image:9cda) ![](text:image:946f)
%[text] Don't Repeat Yourself (DRY)!
%[text] 
%[text] 
for ii = 1:10 %[output:group:24ed052c]
    disp(ii) %[output:789cdb12]
end %[output:group:24ed052c]
%[text] 
%[text] 2026-10-05: first run (dry run): V1 switched to any variable names after six false failures. Note that 1% also accepts g = 9.8 and g = 10 (author: fine).
%[text] 2026-10-05: author review of the first run: S1 minimum lowered to 2 text and 2 code blocks; plain (non-live) scripts noted in the class summary, not in individual feedback; no submission leaves the grade blank.

figure() %[output:3d7886ac]
clf() %[output:3d7886ac]

principal = 23500;
plot(30, principal, 'o') %[output:3d7886ac]
%%

hold on; %[output:53c371a7]
for ii = 31:55
    rtn = principal * r;
    principal = principal + rtn;
    
    plot(ii, principal, 'o') %[output:53c371a7]
end


xlabel("Age [years]") %[output:53c371a7]
ylabel("Principal [$]") %[output:53c371a7]
grid("on") %[output:53c371a7]
%%
%[text] ## Analytical Model
%[text] Compounded annual interest
%[text] $A = P(1+r)^{t}$
P = 23500;
r = 0.05;
t = 25;

A = P*(1+r)^t %[output:3ad6cd19]
%[text] Compare that to our numerical solution
principal %[output:43ad2bf2]
%[text] Now with vectors!
tt = linspace(1,30,10000) %[output:9f70afb8]
aa = P*(1+r).^tt %[output:3f075556]
hold on %[output:7f063a54]
plot(tt+30,aa,'LineWidth',2) %[output:7f063a54]

